insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 1, 'What is a stage in an unloading sequence?', '["A fixed interval of time counted from the start of the compressor.", "The period during which one valve is being set on the test rack.", "The state of the string at the moment the point of injection arrives at a given valve, numbered by which valve is taking the gas rather than by any clock reading.", "A depth band lying between two mandrels in the completion."]'::jsonb, 2, 'midDecrementKnifeEdge carries 7 valves and therefore 7 stages, its surface injection pressure stepping from 1164.7000 psia down to 1004.2000 psia.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 2, 'On midDecrementKnifeEdge the surface injection pressure falls at every transfer while the pressure at the point of injection rises to 1279.335341477 psia at stage 4 and then falls back to 1237.985650690 psia at the packer. Why does it turn over?', '["The extra gas weight bought by another 957.138060181 ft of depth stops covering another 26.75 psi of decrement.", "The compressibility factor of the injection gas passes through its minimum near that depth, so the column stops gaining weight while the surface pressure keeps stepping down.", "The unloading gradient of 0.09 psi/ft begins to dominate the annulus once the fluid level has been driven past the middle of the string, which caps the pressure at depth.", "The kill fluid gradient of 0.46 psi/ft takes over below valve 4."]'::jsonb, 0, 'The spacing increments fall from 1819.125755854 ft on the first transfer to 430.416867128 ft on the last, so the depth bought per stage shrinks all the way down.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 3, 'Every golden stage row of this design puts the fluid level exactly at the valve depth, 2354.019705701 ft at stage 1 and 9000.000000000 ft at stage 7. What is that number?', '["A converged result of the annulus and tubing balance, obtained by iterating the level until the injection and unloading columns meet at the valve.", "A measurement carried through from the last survey run on the well.", "A coincidence of this case, since its decrement happens to match its kill gradient.", "An assertion that the well unloads cleanly to each new valve and no further, rather than a level anybody solved for."]'::jsonb, 3, 'The transfer itself is computed rather than tested, so a design that would stall part way still prints a complete seven stage table.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 4, 'The first transfer moves the point of injection 1819.125755854 ft deeper and the last one moves it 430.416867128 ft, for the same surface pressure each time. What does that show?', '["The decrement is applied to the deeper valves at a reduced value, which is what the surfaceClose convention does once the fluid level passes the middle of the string.", "The same 26.75 psi buys steadily less hole as the string goes deeper.", "The minimum spacing of 275.0 ft is binding on the last transfer, so the recursion has stopped choosing a depth and is enforcing a floor instead.", "The kill fluid gradient of 0.46 psi/ft falls as the well unloads, which shortens each successive step down the string."]'::jsonb, 1, 'The injection line and the unloading line converge with depth, so the race between them flattens and a design that looks generously spaced at the top buys almost nothing at the bottom.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 5, 'What does the annulus model behind every stage casing pressure refuse to include?', '["The compressibility factor of the injection gas.", "The temperature profile down the annulus.", "Friction, velocity and injection rate, since the column is static, so the casing pressure at every stage is shut in gas and not a flowing column.", "The weight of the gas itself, a rule of thumb standing in for it."]'::jsonb, 2, 'Intermittent lift is not modelled anywhere in the module either, so the whole sequence describes a continuous flow string.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 6, 'The six charged valves of midDecrementKnifeEdge carry closing surface pressures of 1112.854990002 down to 1013.861991357 psia. Why do the deeper ones close at lower surface pressures?', '["The dome sits hotter at depth and the column carried back up is longer, and the two effects do not cancel.", "The port on the deeper valves is chosen larger by the throughput calculation, which raises the port to bellows ratio and drags the closing pressure down with it.", "The deeper valves are charged to a lower dome pressure on the test rack.", "The casing at depth is heavier, so less dome charge is needed."]'::jsonb, 0, 'Valve 7 is an orifice at 9000.000000000 ft and carries no closing pressure at all.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 7, 'Against valve 1 the engine surface margin runs 25.095008888 psi at stage 2 and then -1.654991112, -28.404991112, -55.154991112, -81.904991112 and -108.654991112 psi. What fixes the step between them?', '["The dome charge cools a little at every transfer as the well unloads, which lowers the closing surface pressure by the same amount that the casing falls.", "Only the casing is moving, so the margin falls by the decrement at every transfer.", "The spread of 55.525309973 psi is consumed in equal instalments, one for each remaining stage in the sequence.", "The unloading gradient of 0.09 psi/ft fixes it."]'::jsonb, 1, 'A valve shut on a casing that only falls stays shut, which is why the open valve list at any stage is a run of the shallowest valves and never a scattered set.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 8, 'At stage 3 the oracle reads valve 1 as 1180.251805285 psia against a dome of 1182.023754759 psia, while the engine reads 1111.2000 psia against 1112.854991112 psia. What has that established?', '["That the engine is the more accurate route, since its two numbers are smaller.", "That the oracle and the engine disagree on the margin, which is an open defect.", "That the two margins should be averaged to obtain the true one.", "Two roads sharing no numerical method reach one verdict, the oracle testing at valve depth and the engine at surface, and agreement holds across all 7 stages."]'::jsonb, 3, 'The oracle marches a forward RK4 column while the engine inverts a coarser one, so the agreement is evidence rather than arithmetic.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 9, 'The smallest stage gas rate anywhere on this design is 1347.108582683 Mscf/d against a target of 600.0 Mscf/d. What does the passes flag tell a reviewer?', '["That the string is comfortably sized, so throughput can be signed off and the remaining checks confined to the spacing.", "That the valves will pass about twice the gas the design needs, Thornhill and Craver returning what a valve delivers once its stem is fully open.", "Very little, since it is true with that much room on every stage of every published case.", "That the deeper valves are choked, because a rate that far above target is reached only in the critical flow regime."]'::jsonb, 2, 'Valves 1 to 3 pass their gas in the critical regime and valves 4 to 7 in the subcritical one, and the flag reads true across that boundary without noting it.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 10, 'Thornhill and Craver returns 1946.971134442 Mscf/d through the orifice at the packer. How should that figure be read?', '["As an upper bound, because an orifice equation does not know a real valve throttles on its stem before it is fully open.", "As the injection rate the string will carry once the sequence completes, since the deepest point of injection sets the rate for the whole well.", "As a lower bound, the correlation being conservative by design.", "As the rate at which the valve closes on its own spread."]'::jsonb, 0, 'Nothing in the module solves for an injection rate, so the annulus stays a shut in column while the throughput correlation is evaluated beside it.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 11, 'Why is a closing surface pressure a property of the valve rather than of the stage at which it is tested?', '["It is recomputed at every stage from the casing pressure then acting on it.", "It is fixed by the dome, the 0.77 in2 bellows and the 0.25 in port, and the sequence walks a falling casing past six numbers set before it starts.", "It is the casing pressure at which a stage is declared complete.", "It is the surface pressure carried at the stage where the valve opens."]'::jsonb, 1, 'Change the port and all six of those numbers move, while the sequence that walks past them is unchanged.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 12, 'Valve 1 of constantPressurePPO is tested at 1114.7 psia against a closing surface pressure of 389.713022538 psia and called open. What is wrong with the verdict?', '["The closing surface pressure has been evaluated at the 60 degF test rack temperature rather than at valve temperature, which is why it lands several hundred psi below the casing.", "The constant pressure convention holds the surface injection pressure fixed at every stage, so no casing drop ever accumulates and no valve can ever be shown to close.", "The valve is an orifice and so has no closing pressure to test.", "The dome of a production operated valve balances against the tubing, so the engine has inverted it up a casing column and then judged it on the casing."]'::jsonb, 3, 'The rule it should face, 357.547660568 psia of tubing at valve depth against a dome at valve temperature of 409.797201414 psia, misses by 52.249540846 psi and calls it shut.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 13, 'deepHighPressure carries 7 valves on 40.00 psi per valve and never multipoints, while midDecrementKnifeEdge carries 7 valves on 26.75 psi per valve and multipoints four times. What does a valve count tell you?', '["That the two are equivalent in unloading behaviour, the difference lying in the kill fluid gradient each was spaced against rather than in the decrement.", "That both strings unload identically.", "Nothing, because what separates the two is the decrement measured against the spreads.", "That seven valves is the natural count for a 9000 ft well."]'::jsonb, 2, 'At stage 2 of deepHighPressure valve 1 has a spread of 39.204722432 psi against a casing drop of 43.324677700 psi, so one transfer already outruns the widest spread in that string.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 14, 'In a stage row of midDecrementKnifeEdge, which reported quantity is set by declaration rather than computed?', '["The fluid level.", "The injection pressure at valve depth, which is read off the static gas column march at the stage casing pressure.", "The gas rate through the valve, which comes from the Thornhill and Craver orifice correlation at the stage pressures.", "The production pressure at valve depth, which is a straight line on the declared unloading gradient of 0.09 psi/ft."]'::jsonb, 0, 'Stage 4 reports a level of 6871.141344247 ft, exactly the valve depth, while the production pressure runs from a wellhead of 154.7 psia.'),
  ('gaslift', 'advanced', 'module', 'm01-unloading-is-a-sequence', 15, 'A design that would stall part way through unloading still prints a complete seven stage table. Why?', '["The stage table is generated from the spacing recursion before the unloading check runs, and any stage that fails the check is reported with its warning suppressed.", "The engine asserts the transfer rather than testing it, computing what the string looks like once the point of injection has arrived.", "The fluid level is solved for at every stage, so a stall shows up as a level sitting above the valve rather than as a missing row.", "Stalls are reported through the warnings array instead of through the stage list."]'::jsonb, 1, 'There is no inflow relation and no multiphase outflow in the module, so nothing in it can find out whether the well actually lifts to the next valve.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 1, 'Across the six charged valves of the published midDecrementKnifeEdge case, what is the open flag actually testing?', '["Whether the injection pressure at valve depth still exceeds the production pressure there by more than the transfer differential of 60.0 psi that the case declares.", "Whether the casing drop since that valve''s own opening stage has passed the valve''s spread, measured at valve depth.", "Whether the port is large enough to pass the design target of 600.0 Mscf/d.", "Whether the valve sits above the current point of injection."]'::jsonb, 1, 'Valve 4 opens with a spread of 32.272254090 psi against a drop of 32.122462454 psi, and the 0.149791635 psi between them is the whole knife edge.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 2, 'Why does comparing a valve''s spread against the 26.75 psi surface decrement pick the wrong valves?', '["The decrement is applied only to the valves lying below the point of injection.", "The spread is quoted at the 60 degF test rack and the decrement at valve temperature.", "The decrement itself changes at every stage as the fluid level falls.", "The comparison happens at valve depth, where the drop a valve feels runs from 28.652797457 psi at valve 1 to 33.355029522 psi at valve 6 on a column that grows heavier with the pressure it carries."]'::jsonb, 3, 'Only at surface does a transfer remove exactly 26.75 psi, and the gap between the typed number and the felt one widens with depth.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 3, 'Valves 5 and 6 of that design carry spreads of 26.401432257 and 21.310451869 psi. Why do stages 6 and 7 come out clean?', '["Each of those spreads is narrower than a single stage of casing drop at that valve''s depth, so the valve shuts at once.", "Those valves sit below the point where the injection line and the unloading line cross, so the casing never reaches them at a pressure high enough to hold them open.", "The orifice at the packer takes the whole of the gas as soon as the sequence reaches it, which shuts every charged valve above it at the same moment.", "They are tested against the operating surface pressure of 1064.7 psia instead."]'::jsonb, 0, 'The spreads shrink with depth while the drop per stage grows, so both effects push the deeper valves toward shutting cleanly.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 4, 'The four multipointing stages on this case are 2, 3, 4 and 5. What does that pattern say about where multipointing lives?', '["Multipointing is always a trouble of the shallow valves, because a valve''s spread is largest where the casing pressure is highest and falls away monotonically below it.", "Multipointing follows the point of injection, so it appears wherever the fluid level happens to sit at the moment the transfer takes place.", "It is a property of this design rather than of the top of a string in general.", "It shows the stages near the packer are protected by the minimum spacing of 275.0 ft, which keeps the deeper valves far enough apart to shut."]'::jsonb, 2, 'On a design with a smaller decrement the same shrinking spread keeps valves open further down and the pattern reverses.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 5, 'Stage 5 of the published knife edge case is true at 0.149791635 psi of closing margin at valve depth. What is the conclusion to draw?', '["The engine ought to report the verdict as false, the margin lying inside its own numerical error.", "The most consequential boolean the design function emits is decided by a fraction of a psi on a system carrying 1164.7000 psia at surface and 1279.335785 psia at valve 4, so the margin is the quantity worth reading.", "The nine digits carried through the report show that the answer is stable.", "The stage wants rerunning at a finer column step count to settle it."]'::jsonb, 1, 'The same stage carries -59.034480503 psi on valve 1, and both verdicts arrive in exactly the same shape with no distance attached to either.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 6, 'The engine raises four multipointing warnings on this case, worded identically apart from the stage and valve numbers. What does a design review lose?', '["The identity of the valve left open, since the wording names only the stage and a reviewer has to work back through the spacing table to recover which valve it was.", "The count of stages affected, because repeated warnings of one class are collapsed into a single entry before the design is returned.", "Nothing, since the closing margins are returned alongside the warnings.", "Any indication that the stage 5 warning is a coin toss while the stage 2 warning, at 26.872512516 psi of margin, is not."]'::jsonb, 3, 'The closing margins live in the goldens, cut by the oracle, and not in what the design function returns.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 7, 'Sweeping the decrement on the published inputs gives a stage 5 surface margin of 0.011681097 psi at 26.85 psi per valve and -0.044863189 psi at 26.90 psi per valve. What follows for a sweep?', '["The flip has a location and a slope on this axis, so a step finer than a tenth of a psi per valve is needed to find it.", "The verdict is discontinuous here, so no resolution will place the flip and the margin has to be solved for directly rather than sampled at all.", "A whole psi step suffices, the margin walking smoothly across the band.", "The decrement is the wrong axis, since it never reaches the verdict."]'::jsonb, 0, 'The band between 26.80 and 26.90 psi per valve is one nobody would look at twice, which is why the sweep has to be deliberate rather than convenient.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 8, 'Moving every valve from a 0.25 in port to a 0.3125 in port takes the stage 5 surface margin from 0.124769727 to 15.249903355 psi and adds a multipointing stage. What shape of sensitivity is that?', '["A continuous sensitivity, of the same shape as bellows area.", "A numerical artefact of reselecting ports part way through a sweep.", "A catalogue step, the port reaching the verdict through the port to bellows ratio in one jump with nothing available in between the two sizes.", "A linear response, the margin scaling with port area."]'::jsonb, 2, 'Bellows area is the continuous half of the same ratio, moving the margin from 6.629477446 psi at 0.62 in2 to -3.758264661 psi at 0.9 in2.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 9, 'The stage 5 surface margin is frozen at 0.124769727 psi from a design gas rate of 400 through 1400 Mscf/d and then jumps to 15.249903355 psi at 1600 Mscf/d. Why?', '["The throughput correlation crosses from the critical regime into the subcritical one somewhere between those two targets, which changes the pressure the valve is judged at.", "The gas rate reaches the verdict only through port selection.", "The spacing recursion is rerun above 1400 Mscf/d, moving every valve depth below valve 1 and with it every dome charge in the string.", "The margin is clipped to the printed precision until the change exceeds it, so the movement in between is real but never shown."]'::jsonb, 1, 'A coarse sweep can miss the flip and a fine one finds nothing between the steps, so the resolution has to match the mechanism rather than the axis.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 10, 'Before engines PR #110, what did the validation oracle''s unloading routine do?', '["It walked the valves and appended an empty open valve list for every stage, without ever evaluating the closing condition.", "It evaluated the closing condition at surface by the same inversion the engine uses, so the two agreed by construction and could never disagree on any published case.", "It compared the engine''s verdict against the warnings array.", "It raised an exception on every case, so the gate was skipped under an explicit allowance."]'::jsonb, 0, 'No unloading key was written into the goldens at all, so there was no committed answer to compare against and no comparison that could fail.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 11, 'Why is a stub oracle worse for the multipointing verdict than having no oracle at all?', '["A stub consumes the same runtime as a real check, so the suite grows slower without gaining anything and the cost eventually forces the whole gate to be dropped.", "A stub writes an incorrect answer into the goldens, so every later comparison is made against a value already known to be wrong.", "Coverage that is not coverage also suppresses the question, whereas an ungated function is visibly ungated and gets asked about.", "The two are equivalent, neither one performing a check."]'::jsonb, 2, 'The extraction gate''s whole premise is that an independent implementation checked the engine, and here it was passing on a check that had never been performed.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 12, 'The engine''s own test asserted only that a decrement far below every spread multipoints and one far above does not. What was wrong with that?', '["It used the engine''s own inverted surface column on both sides of the comparison, so the test could only ever confirm that the inversion was self consistent.", "It ran on a case that was never published, so its numbers could not be quoted.", "It asserted on the warnings text instead of on the boolean.", "It pins the two ends, so it tests the direction of the rule and not the rule, while every real design sits in the 20 to 50 psi per valve band."]'::jsonb, 3, 'midDecrementKnifeEdge was added as a fourth published case, spaced on 26.75 psi per valve, precisely to sit in the middle of that band.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 13, 'How does the closed oracle reach the multipointing verdict, and why does the route matter?', '["It reruns the engine at a much finer column step count and compares the two results, which makes the check a convergence study on one routine rather than a second opinion.", "It evaluates the published closing rule at valve depth off a forward RK4 column, sharing no code and no numerical method with the engine''s surface test.", "It reads the verdict from the warnings the engine raises and confirms the count of warnings matches the count of stages flagged as multipointing.", "It inverts the same coarse column the engine uses and compares at surface."]'::jsonb, 1, 'The goldens gained 28 stage rows and 85 closing margin rows, and verdict agreement is exact on all 22 stages of the three IPO designs.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 14, 'What did the new oracle find on its first run against constantPressurePPO?', '["Verdict disagreement on all five of its later stages, the engine reporting multipointing at stages 2 through 6 while the oracle finds every stage clean.", "Exact agreement, which is what pinned the case as a reference.", "A disagreement of 2.3e-4 psi on the closing margins.", "That the case carried no charged valves to test."]'::jsonb, 0, 'That disagreement is the pinned PPO divergence, and it had been sitting in a shipped function the whole time the stub was reporting nothing.'),
  ('gaslift', 'advanced', 'module', 'm02-multipointing', 15, 'A multipointing warning on an IPO string and the same warning on a PPO string call for different responses. Why?', '["PPO valves cannot multipoint at all, a production operated valve being held open by tubing pressure and tubing pressure only rising as the well unloads.", "The warning on a PPO string is raised under a different stage numbering, the sequence counting from the orifice upward on a production operated design.", "On a PPO string the verdict is an artefact of a pinned divergence.", "The two families use different spreads, so one warning carries a different closing margin and the numbers cannot be compared across them."]'::jsonb, 2, 'The engine clears the casing side threshold by 379.101060 to 724.986977 psi while the tubing side rule those valves should face misses by 31.822047 to 52.249541 psi.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 1, 'The function returns 8000.000000000 ft with limitedBy reported as depth. What has happened?', '["A crossing was found exactly at the deepest tabulated row, where the injection pressure stands above the production pressure by precisely the 100.0 psi transfer differential.", "The maximum depth constraint became active inside the search, so a deeper crossing was clipped back to the bottom of the well.", "The table ran out with the gas still winning.", "The injection pressure fell below the production pressure at the last row, so the deepest feasible point is the packer itself."]'::jsonb, 2, 'At 1214.7 psia of surface pressure the returned injection pressure is 1460.125387434 psia against a production pressure of 1146.700000000 psia, a pair never solved for.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 2, 'Walking the surface injection pressure from 814.7 to 1014.7 psia buys 5720.258653058, 6227.361380141, 6732.128853068, 7236.797664483 and 7739.815725361 ft. What does the exchange rate look like?', '["About five hundred feet for every 50.0 psi, steady right up to the point where it buys nothing at all.", "It accelerates with pressure, since the injection column grows heavier as it is pressured up and each extra psi at surface arrives at depth multiplied.", "It falls away sharply above 900 psia as the traverse steepens.", "It is not a rate at all, the answer being clamped throughout."]'::jsonb, 0, 'Pushed the other way the depth collapses faster than the pressure does, 514.7 psia buying 2647.944878219 ft and 314.7 psia buying 538.553047921 ft.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 3, 'What does the calculation return when the gas loses at the very first tabulated row?', '["A null depth with an explicit warning attached.", "A depth of 0 still labelled as limited by pressure, which is the engine''s way of saying the well will not lift at all on that injection pressure.", "The wellhead pressure of 164.7000 psia and no depth.", "An error, no crossing existing to report."]'::jsonb, 1, 'Only one of the three return shapes is a crossing, and the other two are stops that the limitedBy field has to be read to tell apart.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 4, 'The published flowing traverse arrives as 9 rows at 1000.0 ft spacing. Why does the module refuse to compute one for itself?', '["The traverse depends on the injection depth being solved for, so computing it inside would make the calculation implicit, and the engine avoids iterating on two curves at once.", "A traverse computed inside the module could not be validated against the goldens, since the published cases record only the crossing and never the curve behind it.", "It would need a reservoir pressure, which the caller is not asked to supply.", "It solves no multiphase outflow and carries no inflow relation, so the production side of the crossing is deliberately somebody else''s answer."]'::jsonb, 3, 'The engine header expects the caller to build the traverse from a validated nodal model rather than have this module invent a gradient.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 5, 'Resampling the same traverse with the injection column held converged gives a crossing of 7718.332998046 ft at 3 rows and 7739.814701427 ft at 9 rows. What does that establish?', '["The row spacing of the table is an input in its own right, and the answer moves by more than twenty feet with it while nothing in the result reports the spacing at all.", "That a traverse should always be tabulated at 1000.0 ft to match the published case.", "That the coarse table is nearer the truth, since it smooths the curve.", "That the crossing is insensitive to the tabulation."]'::jsonb, 0, 'Those refinement rows are a teaching construct, a monotone cubic built through the published rows, and they reproduce every published row exactly.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 6, 'Marching the injection column from 8 samples to 2560 moves the crossing from 7739.840298490 ft to 7739.814701286 ft on the published 9 row table. What is the lesson?', '["The column march is the dominant source of error here, and the hundredths of a foot it moves would grow into tens of feet on a deeper well or a heavier gas.", "Both sides converge together, so refining either one is enough to establish that the reported crossing is right to within a foot.", "Refining the side that is easy to refine changes almost nothing, because the traverse rows are what control the depth.", "The march has not converged even at 2560 samples and wants more steps."]'::jsonb, 2, 'The traverse rows usually arrive fixed, from a file or from somebody else''s software, which is exactly what makes them awkward to refine.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 7, 'State the condition that defines the deepest injection point.', '["The depth at which the static injection gradient and the flowing production gradient become equal, so that the two curves run parallel from there downward.", "The depth at which the injection pressure exceeds the flowing production pressure by exactly the transfer differential.", "The depth at which the two pressures are equal.", "The depth at which the injection pressure reaches its largest value."]'::jsonb, 1, 'On the published case the committed answer is 7739.814701036 ft, with 1209.238206006 psia against 1109.233316949 psia.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 8, 'Why can the residual the function reports not be read as a measure of how good the depth is?', '["The residual is reported in psi while the answer is in feet, and converting between them needs a gradient the function never carries into its output.", "The residual is evaluated at the tabulated row above the crossing rather than at the crossing, so it understates the error by roughly one row of pressure.", "The gate allows 0.5 psi, which is far too loose for a crossing quoted to nine decimal places, so the residual is never the binding check.", "Both sides of it are read off the same pair of chords, so it says only that the chords agree."]'::jsonb, 3, 'The reported residual stays small at every tabulation spacing while the depth error changes by more than twenty feet.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 9, 'As the shipped engine runs the published case it reports a residual of 4.6770e-3 psi. How far is that answer from the converged crossing?', '["It sits 1.317711139 ft and 0.032909074 psi away, where the true residual is 1.58211e-1 psi, 33.83 times the number reported.", "It sits within a hundredth of a foot of the converged crossing, which is why the reported residual is small, the two being consistent measures of one error.", "It is 22.800438454 ft away, that being the error carried by the coarsest table.", "The distance cannot be stated, no converged crossing having been computed."]'::jsonb, 0, 'The converged crossing against a continuous traverse and a converged column sits at 7741.133436499 ft, its two pressures separated by exactly 100.0 psi.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 10, 'Holding the published case at 1014.7 psia and moving only the transfer differential gives 7949.755733309 ft at 75.0 psi and 6894.703876604 ft at 200.0 psi. What is the differential?', '["A tolerance on the crossing search, tightened to refine the answer.", "A margin the designer insists on keeping between the two curves, and insisting on more of it costs hole at much the same feet per psi across that range.", "The pressure drop across the valve port at the point of injection.", "The allowance made for the weight of the gas in the annulus."]'::jsonb, 1, 'Below 75.0 psi the answer clamps to 8000.000000000 ft and the differential stops binding, which is what the limitedBy field reports.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 11, 'At 314.7 psia of surface pressure the crossing sits at 538.553047921 ft with a production pressure of 218.555304792 psia, and at 1014.7 psia it sits at 7739.815725361 ft with 1109.233464452 psia. What have those figures established?', '["That the deeper point of injection roughly quintuples the drawdown available, production pressure at the point of injection being what sets the inflow.", "That the exchange rate between surface pressure and depth is linear, so the depth may be interpolated at any intermediate compressor setting.", "Pressures at a depth, and nothing whatever about the rate the well would make there.", "That the well will not lift at the lower of the two settings."]'::jsonb, 2, 'There is no inflow relation in the module, so turning feet into barrels is a nodal calculation somebody else has to do.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 12, 'Why is the deepest injection point a ceiling rather than a design answer?', '["It is computed before the valves are spaced, so it moves once they are.", "It is quoted to nine decimal places and carries no uncertainty.", "It ignores the minimum spacing rule governing the deepest mandrel.", "It says only where gas can still get in against one traverse on one injection pressure with one margin, leaving nothing in hand for a heavier traverse or a compressor that drifts."]'::jsonb, 3, 'None of the spacing rules that produce a real string appear anywhere in this calculation.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 13, 'A traverse table with the wrong holdup in it is handed to the function. What happens?', '["It returns a crossing to nine decimal places, having no way of telling that curve from a right one.", "It detects the inconsistency between the traverse and the injection column and returns limitedBy pressure at a depth of 0, which is its way of rejecting the input.", "It reports a large residual, since the injection side is computed internally and would no longer meet the erroneous traverse inside the gate of 0.5 psi.", "It refuses the table, the rows having to be monotone in pressure."]'::jsonb, 0, 'Nothing in the returned result reports the row spacing, the provenance of the traverse or its curvature.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 14, 'Of the three ways this function can return, how many represent a crossing that was actually solved for?', '["Two, since a return at the deepest tabulated row is still a solved crossing whenever the injection pressure there stands above the production pressure.", "All three, which is why the field exists.", "One, the case where limitedBy is pressure at a depth above the end of the table.", "Two, the pressure limited returns at either end."]'::jsonb, 2, 'At 1214.7 psia the two returned pressures are 1460.125387434 and 1146.700000000 psia, which are not 100.0 psi apart.'),
  ('gaslift', 'advanced', 'module', 'm03-the-deepest-injection-point', 15, 'Which quantity does the module report, and which does it decline to convert that report into?', '["It reports a pressure at depth, and it declines to convert that into the surface pressure a compressor would have to hold.", "It reports feet, and it declines to report rate.", "It reports a residual in psi, and it declines to convert that into the depth uncertainty which the residual would imply.", "It reports a valve depth, and it declines to convert that into the port size a valve at that depth would need."]'::jsonb, 1, 'Deeper injection puts gas into a longer column, and turning that into drawdown or revenue needs an inflow relation the module does not carry.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 1, 'How does deepestInjectionPoint locate the depth at which the gas stops winning?', '["It bisects the interval between the two bracketing rows until the margin falls below 0.5 psi.", "It marches the gas column downward in fine steps until the margin changes sign, then stops.", "It subtracts the production pressure and the transfer differential from the injection pressure at every tabulated depth, then draws a straight line through the margin between the last positive row and the first negative one and takes its zero.", "It fits a cubic through the traverse rows and solves that cubic for its root."]'::jsonb, 2, 'There is no bracketing loop and no tolerance to tighten anywhere in that search, only one division.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 2, 'What are the two quantities that the residual reported at the crossing is the difference between?', '["Two chords, one drawn across the injection curve samples and one drawn across the traverse rows.", "The converged injection pressure and the converged production pressure, both evaluated at the depth the interpolation returned, which is why the figure measures distance to the true crossing.", "The injection pressure from the gas column march and the production pressure read off a monotone cubic that the engine itself fits through the rows of the flowing traverse.", "The transfer differential the caller declared and the pressure difference the solver actually achieved between the two continuous curves at the depth it settled on."]'::jsonb, 0, 'The interpolation puts the depth exactly where those two straight lines cross, so the residual there is driven near zero by construction.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 3, 'Why is the published case on its own a poor advertisement for this defect?', '["The reported figure sits well inside the 0.5 psi gate, so the published case was never meant to exercise the crossing search at all and no reader should have expected it to expose anything.", "The ratio of 33.83 reads as a curiosity, while the same mechanism on a curved teaching traverse gives 678.26.", "The published depth error is smaller than the tabulation spacing.", "The residual is reported in psi rather than in feet of depth."]'::jsonb, 1, 'That 33.83 is the shipped engine line on the published case, and what separates it from 678.26 is the curvature of the traverse.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 4, 'Across a refinement of the injection curve the reported residual rises from exactly 0.0000e+0 psi at 8 samples to 4.8890e-3 psi at 2560 while the depth improves. What does that establish?', '["The 8 sample column is the more accurate of the two, since a residual of exactly zero can only be produced by an exact solution of the crossing condition.", "The injection samples and the traverse rows carry error of opposite sign, so refining one of them exposes error that the other had been masking all along.", "The gas column march is unstable at low sample counts.", "The reported residual is not measuring the error, because it grows while the calculation gets better."]'::jsonb, 3, 'The 8 sample row carries the worst depth in that study, so the smallest reported residual belongs to the poorest answer.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 5, 'Which knob in this calculation is cheap to turn, and which one carries the error?', '["Both are set by the caller, and the traverse is the cheaper of the two to refine.", "The injection column is built inside the module and any caller can ask for more samples, while the traverse arrives from a nodal model outside it at whatever row spacing that model happened to print.", "The transfer differential is the cheap knob and the surface injection pressure is the expensive one.", "The gas gravity is cheap to change and the temperature profile is what carries the error."]'::jsonb, 1, 'That asymmetry is the whole trap: the refinable knob does nothing and the fixed one decides the answer.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 6, 'deepestInjectionPoint allows itself 0.5 psi of residual at the crossing. What does passing that gate establish about the depth?', '["Very little, since a four row tabulation of a curved teaching traverse reports 1.5907e-2 psi and carries a depth 60.420814470 ft shallow.", "It establishes that the interpolated depth reproduces the transfer differential the caller declared to within half a psi, which is the tolerance the crossing condition itself was written against.", "It establishes that the traverse rows were spaced finely enough for the answer.", "It establishes that the gas column march behind the injection side has converged."]'::jsonb, 0, 'The residual it cannot see on that tabulation is 1.0789e+1 psi, far outside the gate the reported figure cleared.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 7, 'On a refinement of the published traverse the reported residual falls from 5.3979e-5 psi at 33 rows to 2.5888e-5 psi at 65 rows while the depth error grows from -0.000933670 ft to 0.002834866 ft. What follows for an acceptance rule?', '["The study should be stopped at 33 rows, since that row carries both the smaller residual and the smaller depth error and is therefore the converged answer of the whole refinement.", "The gate should be tightened to a tenth of its present value, because a threshold of 0.5 psi is plainly far too loose to catch a depth error of the size this refinement exposes.", "No threshold placed on the reported residual can be a safe acceptance test for the depth.", "The traverse rows should be spaced by curvature."]'::jsonb, 2, 'The two columns move independently, so the reported figure is not even monotone in the quantity a reader would use it to judge.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 8, 'Every depth error in the teaching traverse refinement is negative, at every row spacing tried. What causes that sign?', '["The teaching traverse carries a positive quadratic term, which biases the marched gas column downward at every tabulated depth and pulls the reported crossing with it.", "The transfer differential is subtracted from the injection side rather than added to the production side, which pushes every reported crossing toward the surface.", "The injection curve chord is evaluated at a coarser sample count than the traverse chord, and the coarser of two chords always sets the sign of the answer.", "A chord under a convex traverse sits above the curve, so the crossing is found shallow."]'::jsonb, 3, 'A design built on a crossing found shallow puts the injection point higher than the gas could actually reach.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 9, 'Past 250.0 ft of row spacing on the published traverse the depth error stops falling and starts wandering. Why?', '["The traverse chord is no longer the largest term, so the chord inside the injection pressure curve sets the floor and refining the rows further buys nothing.", "Floating point noise dominates once the rows sit closer than 250.0 ft.", "The engine resamples the traverse below that spacing and discards rows.", "The transfer differential becomes the binding constraint at that resolution."]'::jsonb, 0, 'The wandering values run 0.002834866 ft, 0.002067953 ft and 0.001021648 ft as the spacing halves from 125.0 ft.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 10, 'What check would actually establish something about a returned injection depth?', '["Refine the injection pressure curve from 8 samples up to 2560 and confirm that the returned depth settles in its fourth decimal place, which is the standard convergence demonstration for a marched column.", "Confirm that the reported residual sits well inside the 0.5 psi gate.", "Evaluate the residual at that depth with pressures the solver did not use, or halve the tabulation spacing and see whether the depth moves.", "Check that limitedBy reads pressure rather than depth."]'::jsonb, 2, 'An answer that shifts 60.420814470 ft when the rows change was never converged, whatever it reported.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 11, 'At surface injection pressures of 1214.7, 1414.7 and 1614.7 psia the function returns 8000.000000000 ft every time. What is that number?', '["The depth at which the injection pressure exceeds the production pressure by exactly the transfer differential, which is the same condition every other return of this function satisfies.", "The deepest tabulated row, handed back unchanged with limitedBy reading depth, and not a crossing at all.", "A clamp the engine applies once the reported residual would otherwise breach the 0.5 psi gate, which is why three different surface pressures collapse onto one answer.", "The depth at which the gas column and the traverse cross."]'::jsonb, 1, 'At 1214.7 psia the returned pressures are 1460.125387434 psia against 1146.700000000 psia, nowhere near the 100.0 psi the case declares.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 12, 'Why does this defect look like a release note on the case that ships with the engine?', '["The published case runs to only 8000.0 ft, and chord error accumulates with the length of the well rather than with the shape of the curve the chord stands in for.", "That traverse barely bends, and a chord under a nearly straight line is nearly the line.", "The published case declares a transfer differential of 100.0 psi, which is large enough to swamp any error the interpolation could introduce into the margin it solves.", "The published tabulation carries 9 rows, and 9 rows sits above the count at which the engine switches from chord reading to a higher order interpolation."]'::jsonb, 1, 'Real flowing traverses curve, because holdup and friction both change with depth.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 13, 'Refining the teaching tabulation gives ratios of true residual to reported residual of 689.13, 659.81, 674.71, 669.88, 667.53 and 674.88. Why does that sequence matter more than any single figure in it?', '["The scatter across those figures shows the refinement has not converged, so the whole study should be repeated over a finer set of row spacings before any conclusion is drawn from it.", "It shows the reported residual is always smaller than the true one.", "It shows the depth error falls as the rows are refined.", "The ratio does not decay under refinement, so it is a property of the mechanism and not of one tabulation."]'::jsonb, 3, 'The error and the reported residual fall together, which is exactly why their ratio survives the refinement.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 14, 'What does the engine refuse to do about the tabulation it is handed?', '["It does not resample, it raises no warning when three rows arrive where thirty were needed, and it carries no spacing field in its result.", "It refuses to accept a traverse of fewer than nine rows, and hands back a warning rather than a depth whenever the caller supplies a table coarser than the one the published case ships with.", "It refuses to read the traverse at all unless the caller also supplies the inflow relation that generated it, since the crossing is undefined without one, and it says so in a warning.", "It refuses to extrapolate below the deepest row."]'::jsonb, 0, 'A report that omits the spacing therefore cannot be audited later, because nothing in the result records it.'),
  ('gaslift', 'advanced', 'module', 'm04-a-chord-cannot-see-itself', 15, 'What is the practical rule for setting the row spacing of a traverse before it is handed to this function?', '["Match it to the injection curve sample count the engine defaults to.", "Set it so the reported residual falls below a tenth of the 0.5 psi gate.", "Set it from the curvature of the traverse rather than from whatever the model that produced it printed, then halve it once and read the depth again.", "Use the spacing the published case ships, since that is the validated one."]'::jsonb, 2, 'Do not read the reported residual for this, because it falls on every refinement whether the depth improves or not.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 1, 'What does a single design run fail to tell you about the multipointing verdict it prints?', '["Whether the string reached the target depth, since the stop reason is not reported beside the valve count and has to be inferred from the deepest valve in the table.", "Which valve took the transfer at each stage.", "The surface injection pressure at each stage.", "Whether any input moves the verdict, and how far the design sits from a different answer."]'::jsonb, 3, 'The engine reports no derivative of any output with respect to any input, so distance to a flip is not derivable from one result.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 2, 'Walking the surface decrement on the published knife edge case, where does the stage 5 multipointing verdict flip?', '["Between 26.00 and 26.50 psi per valve.", "Between 26.80 and 26.90 psi per valve, where the stage 5 surface margin passes from 0.011681097 psi at 26.85 to -0.044863189 psi at 26.90.", "Between 27.00 and 27.50 psi per valve, where the margin turns negative.", "It never flips on that axis, because the string multipoints at every decrement."]'::jsonb, 1, '26.75 psi per valve is the published value, and it sits inside a band nobody would look at twice.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 3, 'The stage 5 surface margin walks down through 0.972936966, 0.690214057, 0.407491645, 0.294402819 and 0.181314071 psi as the decrement rises, with no kink where the verdict changes. What does that tell you?', '["The verdict is only the sign of a well behaved quantity, which is why the margin is worth reporting and the boolean is not.", "The flip is a numerical artefact of the spacing recursion rather than a change in the string, since a real change of behaviour would show as a discontinuity in the margin.", "The engine smooths the sweep, which is why neighbouring decrements return margins differing by a constant rather than by the amount the recursion would actually give.", "The sweep resolution was finer than it needed to be."]'::jsonb, 0, 'The only event on that axis is a smooth quantity passing through zero inside a band anyone would call a normal decrement.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 4, 'Why does the surface decrement reach the multipointing verdict at all?', '["It enters selectPort, which chooses the smallest catalogue port that passes the design target at the stage differential, and that port sets the ratio R and so the dome charge on every valve.", "It scales the spread of each valve directly, since the spread is defined as the decrement multiplied by the port to bellows ratio at the valve temperature the spacing recursion returned.", "It moves every valve depth below it and the stage casing pressure at once, so both sides of the closing comparison move.", "It is compared with the transfer differential inside the closing test, which declares a valve open whenever the decrement turns out to be the smaller of those two quantities."]'::jsonb, 2, 'Moving the depths moves every valve temperature, every dome charge and every closing surface pressure with them.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 5, 'A decrement sweep at 26.00, 27.00 and 27.50 psi per valve reads 0.972936966, -0.157951701 and -0.723393096 psi. What is wrong with it?', '["It reports a flip somewhere between the first two points and never sees that the flip lives inside a tenth of a psi per valve.", "It walks the decrement outside the band anyone would use on a real design, so the two negative rows describe a string nobody would space that way and say nothing about the published one.", "It uses three points where four are needed to fit a slope.", "It sweeps the wrong input, since the port is what moves the verdict."]'::jsonb, 0, 'Resolution chosen to make a plot look smooth is not resolution chosen to locate an event.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 6, 'Sweeping the design gas rate on the published knife edge case, what happens between 400 and 1400 Mscf/d?', '["The margin falls steadily toward zero, and the verdict flips once the target passes the throughput that the deepest charged valve can carry at its own stage differential.", "Nothing moves at all, and the stage 5 surface margin holds at 0.124769727 psi across every point.", "The margin rises in proportion to the target, because the throughput correlation is close to linear in rate over that range and the closing test reads its result directly.", "The valve count rises by one."]'::jsonb, 1, 'Reading that flat stretch as robustness is the mistake: it is evidence that the axis had not yet reached its mechanism.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 7, 'By what route does the design gas rate reach the multipointing verdict?', '["Through the throughput each valve passes at its own stage, which the closing test compares with the target.", "Through the stage casing pressure, which falls faster at higher rates.", "Through selectPort alone, which picks the smallest catalogue port that passes the target, and that port then sets the port to bellows ratio, the dome charge and the closing surface pressure.", "Directly, since the design gas rate is an argument of the closing test."]'::jsonb, 2, 'The design gas rate does not enter the closing test at any point, which is why it moves nothing between catalogue steps.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 8, 'A direct port sweep on the published knife edge case returns 0.124769727, 15.249903355, 33.744341944 and 55.613320820 psi at ratios R of 0.063749851, 0.099609142, 0.143437165 and 0.195233918. What does that say about the gas rate axis?', '["The port catalogue is finer than the gas rate axis, so a rate sweep at 50 Mscf/d steps resolves every port change the design could make and no coarser sweep is ever needed.", "R and the design gas rate are independent inputs to the verdict.", "The stage 5 margin is proportional to the port area.", "The gas rate sweep is the port sweep read through a lookup, so it steps when the target crosses a catalogue step."]'::jsonb, 3, 'R is what the dome charge is built on, so a port sweep and a rate sweep are the same experiment reached through different arguments.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 9, 'At 1400 Mscf/d the chosen ports become 0.25, 0.25, 0.25, 0.25, 0.25, 0.3125 and 0.3125 in, yet the stage 5 margin is unchanged at 0.124769727 psi. Why?', '["The stage 5 test is run on valve 4, and valve 4 still carries its 0.25 in port.", "The two valves that changed sit below the point of injection at that stage, and the engine evaluates the closing test only on valves that have already taken a transfer at an earlier stage.", "The throughput of a 0.3125 in port at the stage 5 differential is identical to that of a 0.25 in port once the flow has gone subcritical, so the ratio R is unchanged for both of them.", "The port catalogue does not affect the dome charge."]'::jsonb, 0, 'A port set can change without the verdict changing, which is why the port list and the margin have to be read together.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 10, 'Why can no design return a stage 5 margin between 0.124769727 and 15.249903355 psi on the design gas rate axis?', '["The margin is discontinuous at the flip, because the closing test switches from a surface evaluation to a valve depth evaluation once the string gains an extra multipointing stage.", "No port exists between 0.25 and 0.3125 in.", "Between those two rates the spacing recursion returns a string with a different valve count, so the stage numbers stop lining up and there is no stage 5 left to report a margin for.", "The engine rounds the design gas rate to the nearest catalogue crossing before it spaces the string, so intermediate targets are never evaluated at all."]'::jsonb, 1, 'A curve fitted through those points would describe a valve catalogue that does not exist.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 11, 'Holding the 0.25 in port and walking the bellows area on the published knife edge case, what shape does that axis have?', '["It steps, because the bellows comes out of the same catalogue that the ports do.", "It is flat, since bellows area cancels out of the port to bellows ratio.", "It behaves like the decrement: bellows area is continuous, a larger bellows gives a smaller R and a lower margin, and the verdict follows the sign right across the sweep.", "It reverses in the middle, with the margin rising again past 0.90 in2."]'::jsonb, 2, '0.77 in2 gives 0.124769727 psi and 0.90 in2 gives -3.758264661 psi, so the verdict turns false between them.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 12, 'Walking the transfer differential from 40.0 to 100.0 psi produces two different kinds of change. What are they?', '["The deepest valve moves off target depth between 50.0 and 60.0 psi, and the multipointing stages then renumber themselves so that stage 5 is reported against a different valve entirely.", "The verdict gains stage 5 between 50.0 and 60.0 psi with the string unchanged, and by 80.0 psi the string has gained a valve.", "The margin turns negative and then positive again.", "The valve count falls while the deepest depth rises."]'::jsonb, 1, 'Every row of that sweep still reaches 9000.000000000 ft, so the stop reason alone would have hidden both changes.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 13, 'Why can the stage 5 margins at unloading gradients of 0.09 and 0.15 psi/ft not be compared?', '["The unloading gradient enters the production side of every stage row, so the two designs are judged against production pressures that were declared rather than computed and cannot be reconciled.", "The margin is reported at surface on one design and at valve depth on the other, because the engine switches its evaluation point once a string fails to reach the target depth it was given.", "The two designs select different ports from the catalogue, and a margin can only be compared between strings whose valves carry the same port.", "The 0.15 psi/ft design carries 5 valves and stops at 5890.993805513 ft, so it has no stage 5 at all."]'::jsonb, 3, 'A margin swept along that axis compares different valves in different strings, and the deeper rows never reach target depth.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 14, 'What can no sweep of any resolution answer about a design?', '["Which side of a flip is right, and what two inputs do together, since every row of a sweep holds all but one input fixed.", "Where the verdict changes on the axis being swept.", "How far the published design sits from a different answer.", "What margin the deciding stage carries at the published inputs."]'::jsonb, 0, 'A sweep measures distance to an edge, and it never says which direction to be on.'),
  ('gaslift', 'advanced', 'module', 'm05-sweeping-a-design', 15, 'What is wrong with judging a sweep by the number of points in it?', '["The number of points is set by the engine rather than by the caller, since the spacing recursion has to be rerun for every row and the engine caps how many designs one call may return.", "A sweep with many points averages the margin across neighbouring designs, which smooths away the very discontinuity that a stepped axis exists to expose to the reader.", "Four points placed at the catalogue crossings resolve more than forty points on a stepped axis, and they cost less.", "Points are only meaningful where the string underneath them is unchanged, and each additional point on a continuous axis rebuilds the string and so invalidates the comparison."]'::jsonb, 2, 'An axis with no mechanism behind it produces a smooth curve of nothing, and the smoothness reads as confidence.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 1, 'What single habit does the Expert tier say it has taught, applied twice?', '["Refine every numerical method until its reported residual stops moving.", "Read the margin sitting under a verdict, and check a residual against something that did not produce it.", "Report every design output to nine significant figures.", "Space the string before choosing any valve."]'::jsonb, 1, 'The tier ends by asking which numbers in a design are decisions and which are artefacts of how they were computed.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 2, 'A gas lift design is a string rather than a list of valves. What does that imply about the order in which the work is done?', '["The valves are set from the packer upward, so that the deepest depth is fixed first.", "The port is chosen before the string is spaced, since the port fixes the dome charge.", "Every depth below an input you change will move, so the pressures, the decrement, the differential, the gradients, the bellows and the port catalogue are all recorded before anything is computed.", "The stop reason is read before the valve count, since it decides the string."]'::jsonb, 2, 'Spacing is a recursion, so a decrement altered after the fact invalidates every depth beneath the change.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 3, 'Why must the valve count and the stop reason always be reported together?', '["The valve count is capped by the maximum valve input while the stop reason comes from the target depth, so only the pair of them identifies which of those two limits actually bound the string.", "The stop reason changes the units the depths are reported in, since a string that reached target depth is given in ft TVD and one that stopped short in measured depth along the wellbore.", "The engine will not emit a warning list unless both fields are present, and a run that omits either returns its multipointing verdicts as bare booleans with no stage numbers attached to them.", "A string that stopped short is a different object, and its stage numbers do not line up with one that reached bottom."]'::jsonb, 3, 'Six valves stopping at 7207.583657538 ft and seven reaching 9000.000000000 ft cannot be compared stage for stage.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 4, 'Valves 1 to 3 of the published knife edge string pass their gas in the critical regime and valves 4 to 7 in the subcritical one. What does the passes flag do at that boundary?', '["It switches the correlation it compares against, since the orifice equation applies only below the critical pressure ratio and a separate form is used above it.", "It turns false for the subcritical valves.", "It is evaluated only on the valve taking the transfer.", "It reads true across it without noting it, so a string where every valve is choked and one where none are look identical."]'::jsonb, 3, 'Nothing in the returned design records the regime, so the boundary has to be read off the valve rows themselves.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 5, 'Raising the transfer differential from 100.0 to 200.0 psi takes the injection point from 7739.815725361 ft to 6894.703876604 ft. What does a pairing like that give a design review?', '["A price for a decision, stated in feet of hole, that the review can argue with.", "A convergence check on the crossing, since both depths were located on the same tabulation and their difference is therefore free of the chord error that either one carries on its own.", "An inflow answer, since the production pressure at the shallower crossing implies the drawdown that the extra differential has cost the well at its own operating rate.", "A warning that the differential was set too high."]'::jsonb, 0, 'The differential is a margin the designer insists on keeping, and insisting on more of it costs hole.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 6, 'What is the status of the unloading and transfer lines sitting under every stage row and every sweep row?', '["Multiphase traverses computed inside the module from the declared wellhead pressure and the stage gas rate, which is why every stage row carries a production pressure at valve depth.", "Straight lines on constant gradients the caller declares, rather than columns anybody solved.", "Curves marched with the same routine as the annulus gas column.", "Tables the caller passes in beside the flowing traverse."]'::jsonb, 1, 'A real unloading column is neither straight nor constant, so every depth won in a stage table is only as good as the declared gradient.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 7, 'The claim that a small residual proves only self agreement is stated as a general one rather than as a fact about gas lift. What makes it general?', '["It was measured on two traverses of different curvature, and a finding that survives a change of case is by definition independent of the case it was found on.", "The residual becomes dimensionless once divided by the transfer differential, and a dimensionless statement about a numerical method carries across to any other method of the same order.", "Both quantities being subtracted rest on the same approximation, so their difference carries no term that could report that approximation''s error.", "The 0.5 psi gate is arbitrary."]'::jsonb, 2, 'A cheaper version of the same check is to move the tabulation and see whether the answer moves with it.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 8, 'What did closing the validation gap add to the goldens for this module?', '["A second set of goldens cut at valve depth, held beside the surface set so that the two evaluation points could be compared row by row on every design the suite carries.", "An unloading key on every design, 28 stage rows, 85 closing margin rows and a fourth published case.", "A tolerance band on every multipointing verdict, so a stage whose margin falls below a tenth of a psi is now reported as marginal rather than as a plain true or false.", "A resampled flowing traverse at 250.0 ft spacing on every case, which took the chord error out of the crossing and let the injection point be gated at the same tolerance as the column."]'::jsonb, 1, 'Engine agreement came out exact on all 22 stages of the three injection pressure operated designs.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 9, 'The published production operated case carries a spread of -52.249540846 psi on valve 1 and -31.296561503 psi on valve 6. What is that negative sign?', '["The two sides swapped, since the spread routine is handed the tubing pressure as the opening side and the casing as the other.", "A property of production operated valves, whose dome is charged below the tubing pressure at valve depth so that the valve opens on a rising tubing pressure rather than on a rising casing pressure.", "A sign convention the goldens apply to production operated strings.", "Evidence that the bellows area exceeds the port area."]'::jsonb, 0, 'That is one root cause with two symptoms, the other being a closing test run on the casing, and the louder symptom is the one nobody reported.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 10, 'What must a report on an injection point state for the depth to be auditable later?', '["The reported residual and the gate it was measured against.", "The injection curve sample count and the gas gravity.", "The limitedBy value, the row spacing the traverse carried, and whether the depth stayed put under one halving of that spacing.", "The surface injection pressure and the transfer differential."]'::jsonb, 2, 'Nothing in the returned result carries the spacing, so a report that omits it cannot be checked by anybody later.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 11, 'What does a gas lift design turn a gas gravity, a temperature profile and a handful of pressures into?', '["A string of depths and settings that a crew can install and a chart recorder can refute.", "A predicted production rate at the point of injection, which a nodal model can then check against the inflow relation for the well the string was designed for.", "A flowing production traverse for the lifted well.", "An injection rate for the annulus at each stage."]'::jsonb, 0, 'It also prices decisions, which is what lets a design review argue with a string in numbers rather than in opinions.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 12, 'Why does refining the injection pressure curve fail to improve the crossing?', '["The injection curve and the traverse are read at the same depth, so any improvement in one is cancelled by the chord in the other and the reported residual stays exactly where it was.", "The engine caches the injection curve after its first call, so a higher sample count is requested but the crossing is still located against the samples the first pass produced.", "The gas column march is only first order accurate.", "The column was never what was wrong, and the traverse rows are what control the depth."]'::jsonb, 3, 'The column is the cheap knob and the traverse the expensive one, so the refinement that is easy to run is the one that buys nothing.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 13, 'What separates a continuous sweep axis from a stepped one?', '["A continuous axis rebuilds the string at every point while a stepped axis leaves the string alone.", "A continuous axis is an input and a stepped axis is an output.", "A stepped axis always needs a finer sweep than a continuous one.", "A continuous axis moves the margin smoothly so the verdict follows its sign, while a stepped axis does nothing until it crosses a catalogue step."]'::jsonb, 3, 'Forty points on a stepped axis resolve less than four points placed at the crossings, and they cost more to compute.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 14, 'Which of a design run''s outputs is a decision, and which is an artefact?', '["The valve depths are decisions because the designer chose them, while the closing surface pressures are artefacts because each comes from a dome charge computed at an assumed valve temperature.", "The decrement and the transfer differential are decisions, and a clean warning list is an artefact of a comparison nobody printed.", "The stop reason is a decision because the caller declares the target depth, while the stage gas rates are artefacts because they come from a correlation rather than a measurement of the well.", "The valve count is a decision because the caller caps it, while the multipointing warnings are artefacts because the engine raises them from a comparison it never carries into its own output."]'::jsonb, 1, 'A depth read off a traverse tabulated at 1000.0 ft spacing is partly an artefact of that spacing, and nothing in the result records it.'),
  ('gaslift', 'advanced', 'module', 'm06-the-expert-reading', 15, 'Which two results of this module are pinned known divergences rather than absent physics?', '["The absence of any inflow relation and the absence of a multiphase outflow calculation, both of which mean the flowing traverse has to be supplied from outside the module entirely.", "The static annulus column with no friction or velocity in it, and the straight unloading and transfer lines drawn on constant gradients the caller declares rather than anybody solves.", "The production operated closing test, and the residual that the injection point search reports about itself.", "The orifice throughput correlation, and the target depth mandrel''s exemption from the minimum spacing check."]'::jsonb, 2, 'Both were left unfixed because the engine is consumed by a live application, so a report relying on either has to state the limit.'),
  ('gaslift', 'advanced', 'final', null, 1, 'A field report reproduces all seven stage rows of a published knife edge design and states that the well was watched handing over cleanly at each mandrel. Which part of that claim do the rows fail to support?', '["The fluid level in every row is set equal to the valve depth by declaration and the handover itself is asserted rather than tested, so the rows describe what the string looks like once a transfer has happened.", "The surface injection pressures, which are read at the compressor and not computed anywhere inside the design function.", "The gas rate at each stage, which comes from an orifice correlation and is the only quantity in the row with a measurement behind it.", "The injection pressure at depth, which is marched down a static column carrying no injection rate."]'::jsonb, 0, 'A string that would stall part way through unloading still prints a complete seven stage table, because nothing in the sequence is timed and nothing is tested.'),
  ('gaslift', 'advanced', 'final', null, 2, 'A reviewer ranks two candidate strings as equivalent because each lands seven mandrels at target depth, then finds that only one of them injects at two depths during unloading. Which pair of quantities decides that?', '["The number of mandrels and the target depth reached, which together fix how much pressure is available for each handover and therefore whether any valve can stay open past its own stage.", "The casing drop felt at valve depth after each transfer, set against the spread of the valve that has just been left behind.", "The design gas rate and the orifice size at the packer, since a string passing more gas at the bottom holds the shallower valves open for longer than one passing less.", "The kill fluid gradient and the wellhead pressure, which fix where the first valve lands and so fix everything that follows it down the hole."]'::jsonb, 1, 'One design runs 26.75 psi per valve against spreads of 55.525309973 psi and downward, and the other 40.00 psi per valve against 39.204722432 psi and downward.'),
  ('gaslift', 'advanced', 'final', null, 3, 'A designer asks for one more mandrel below the deepest, arguing that the injection pressure at the point of injection was still climbing three transfers earlier. What has changed by the time the string reaches the packer?', '["The kill fluid has been fully displaced, so the unloading gradient no longer applies below the last mandrel and the transfer line cannot be extended any further.", "The stated minimum spacing of 275.0 ft has been reached, which is what stops the recursion.", "The extra gas weight bought by the next few hundred feet no longer covers another 26.75 psi of decrement.", "The gas has entered the subcritical regime through the deeper ports, so the throughput correlation stops returning a rate that could sustain another handover at that depth."]'::jsonb, 2, 'The first transfer buys 1819.125755854 ft and the last one 430.416867128 ft for the same surface pressure, so a string that looks generously spaced at the top is buying very little at the bottom.'),
  ('gaslift', 'advanced', 'final', null, 4, 'A planner argues that a string can safely be asked for far more gas, since every stage clears its target with hundreds of Mscf/d in hand and the smallest stage rate anywhere is 1347.108582683 Mscf/d. Why does that headroom not support the argument?', '["The rates belong to the unloading sequence rather than to the operating point, so they describe a transient the well passes through.", "The rates are computed on a static annulus column, so they carry no friction and are quoted at the wrong pressure.", "The target of 600.0 Mscf/d was itself a declaration, so nothing is proved by clearing it.", "Thornhill and Craver is an orifice equation that does not know a real valve throttles on its stem before it is fully open, so every stage rate is an upper bound rather than a prediction, and the flag reads true across the boundary where valves 1 to 3 pass gas in the critical regime and valves 4 to 7 do not."]'::jsonb, 3, 'Reading the flag alone, a design where every valve is choked and one where none of them are look identical.'),
  ('gaslift', 'advanced', 'final', null, 5, 'Rerunning a design with every valve moved from a 0.25 in port to a 0.3125 in port leaves all seven valve depths exactly where they were while all six closing surface pressures fall. Which two mechanisms account for that split?', '["Spacing is a recursion on the decrement and the declared gradients, none of which the port touches, while the port sets the port to bellows ratio and so moves the dome charge behind every closing pressure.", "The port changes the throughput at each valve, and the spacing recursion is driven by the transfer differential rather than by any rate, so only the closing side of the design responds to it.", "A larger port lowers the test rack opening pressure without moving the dome, and valve depths are fixed by the kill gradient.", "The port enters only the orifice correlation, and the closing pressures fall because the deeper valves sit at higher temperatures."]'::jsonb, 0, 'The ratio moves from 0.063749851 to 0.099609142 on that change, and the six closing surface pressures fall from 1112.854991 and downward to 1083.678962 and downward.'),
  ('gaslift', 'advanced', 'final', null, 6, 'An operator asks whether turning up the compressor rate would change the casing pressures printed against each stage of a design. What settles the question?', '["Rate enters through the transfer differential, so a higher injection rate would raise the casing pressure at every stage by an amount the design function reports as a warning rather than as a number in the table.", "Nothing in the annulus model carries rate at all: the column is static, with no friction and no velocity, so every stage casing pressure is a shut in gas column.", "Rate would change the answer, but only below the point of injection, where the flowing traverse takes over from the static column and friction begins to matter.", "Rate is already in the table, because each stage row carries a gas rate through the valve."]'::jsonb, 1, 'The design gas rate reaches the string only through port selection and the orifice throughput, neither of which touches the pressure in the annulus.'),
  ('gaslift', 'advanced', 'final', null, 7, 'Valve 1 is shut at stage 3 by a surface margin of -1.654991112 psi, and a reviewer asks whether it might reopen later in the run. What answers that?', '["It could reopen, because the injection pressure at depth rises for several stages after that, and the closing test is evaluated on the pressure at valve depth rather than on the pressure at surface.", "It could reopen if a deeper valve shuts first, since the casing recovers the decrement that valve had been carrying and hands it back up the string.", "The casing only ever falls after a transfer, so a valve once shut stays shut.", "It depends on the fluid level, which is declared equal to the valve depth at every stage and therefore moves past valve 1 as the run continues."]'::jsonb, 2, 'That is why the open valve list at any stage is a run of the shallowest valves and never a scattered set.'),
  ('gaslift', 'advanced', 'final', null, 8, 'A validation routine that appended an empty open valve list for every stage, and a crossing search whose residual is the difference between two chords, both get filed as missing checks. What separates the second from the first?', '["The stub never evaluated its condition and would have been caught by anyone reading the code, while the chord check genuinely runs and passes honestly, so neither the code nor the output can reveal that the quantity it compares is blind to its own error.", "The stub was closed by an engines change, while the chord behaviour is still shipping.", "The stub concerned a boolean and the chord concerns a depth, so only one of them can be checked against a published rule at all.", "The stub left no key in the goldens, while the chord leaves a residual that sits inside the gate."]'::jsonb, 0, 'Both leave a consequential answer unchecked while looking checked, which is why they belong in the same family of failure even though only one is visible by inspection.'),
  ('gaslift', 'advanced', 'final', null, 9, 'Working from a spreadsheet, an engineer marks a valve as shutting whenever its spread is smaller than the decrement typed at surface. On a nine thousand foot string, which valves does that rule misclassify?', '["The shallow ones, because the gas column is lightest near surface and a valve there feels a drop noticeably smaller than the decrement typed, which makes the rule shut valves that in fact stay open through the next transfer.", "The deeper ones, because the drop a valve feels at its own depth grows down the hole and reaches 33.355029522 psi at valve 6 while the surface figure stays at 26.75 psi.", "None of them, since spread and decrement are both surface quantities and the comparison is exact.", "All of them equally, because spread is a valve property and decrement a string property."]'::jsonb, 1, 'The comparison the engine actually makes is between the drop since a valve''s own opening stage and that valve''s spread, and on valve 4 those are 32.122462454 psi against 32.272254090 psi.'),
  ('gaslift', 'advanced', 'final', null, 10, 'A review board is asked to reopen a design because a multipointing warning has been raised on a production operated string. What should the board do with the warning?', '["Act on it as it stands, because the closing rule is the same for both valve families.", "Treat it as understated, since a production operated valve carries a negative spread and shuts later than reported.", "Set it aside as an artefact of a pinned divergence, since the closing test inverts a dome that balances against the tubing up a casing column and then compares it with the casing, and the independent check finds every stage of that design clean.", "Ask for the design to be respaced on a larger decrement until the warning clears."]'::jsonb, 2, 'A clean sequence on such a string means nothing either, so the valve family has to be read before the verdict is read at all.'),
  ('gaslift', 'advanced', 'final', null, 11, 'Lifting a design gas rate target from 1400 to 1600 Mscf/d adds a sixth multipointing stage to a string whose valve depths have not moved by a foot. By what route did the target reach the verdict?', '["Through the orifice throughput at each valve, which rose with the target and held the shallower valves open one stage longer than they had been.", "Through the transfer differential, which the design function scales with the target rate so that a larger rate demands a wider margin between the injection and the transfer lines at every valve.", "Through the spacing recursion, which places every mandrel for the declared rate and thereby moves each valve temperature, each dome charge and each closing surface pressure.", "Through port selection, which crossed a catalogue step and so moved the port to bellows ratio, the dome charge and every closing surface pressure with it."]'::jsonb, 3, 'R moves from 0.063749851 to 0.099609142 on that step, and no target between the two catalogue sizes can produce anything in between.'),
  ('gaslift', 'advanced', 'final', null, 12, 'Four warnings from one design run are worded identically apart from their stage and valve numbers, though one sits at 26.872512516 psi of margin and another at 0.149791635 psi. What has to be added before they can be ranked?', '["The closing margin behind each one, which the design function does not return at all.", "A tolerance band on the verdict, which the engine would compute from the spread of each valve and attach to the warning as an uncertainty on the boolean it has just emitted.", "The stage gas rates, which give the reviewer the size of the consequence at each stage and therefore an ordering of the four warnings by what is at risk.", "The valve depths, since a warning raised deep in the string carries more weight than one raised near the surface where the well is easiest to recover."]'::jsonb, 0, 'Those margins live in the goldens, cut by the independent oracle, and not in what the design function hands back.'),
  ('gaslift', 'advanced', 'final', null, 13, 'Two roads to one closing test hand a reviewer 1180.251805285 psia at valve depth and 1111.2000 psia at surface, each against its own threshold, and the reviewer files the pair as a disagreement. What has been misread?', '["The surface figure is the stage casing pressure rather than an evaluation of the closing rule, so it belongs in a different column of the report and cannot be compared with anything the independent check produces.", "The valve depth figure carries the dome at valve temperature and the surface figure carries the dome at 60 degF.", "Nothing disagrees: one road evaluates the rule at valve depth off a forward column and the other at surface off an inverted one, so the two numbers were never meant to match and only the verdict is compared.", "The two roads use different valves, since the surface test runs on the valve taking the transfer."]'::jsonb, 2, 'Verdict agreement is exact on all 22 stages of the three published designs that carry injection operated valves.'),
  ('gaslift', 'advanced', 'final', null, 14, 'A validation suite pins only the two extremes of an input band and reports a pass. What does that establish about the rule under test?', '["That the rule holds throughout the band, because a monotone quantity tested at both ends of its range cannot behave differently anywhere between those two ends.", "That the implementation matches an independent one, which is the whole premise of an extraction gate and the reason a suite is run at all before a function is promoted.", "That the rule is correctly signed but wrongly scaled, which is the usual failure a two point test is designed to expose.", "Only the direction of the rule, since every real design sits in the middle of the band where the verdict is actually decided."]'::jsonb, 3, 'The published case spaced on 26.75 psi per valve was added precisely to sit in the middle of the usual 20 to 50 psi band.'),
  ('gaslift', 'advanced', 'final', null, 15, 'A summary sheet quotes 8000.000000000 ft as the deepest injection point at two different compressor settings, and a reviewer reads the two as the same result. Which field separates them, and what is it saying?', '["limitedBy, which reads depth on both rows: the table ran out with gas still winning, and one of those settings has far more injection pressure in hand at the bottom row than the other.", "The reported residual, which is small on a genuine crossing and large on a row where none was found.", "The production pressure, which equals the deepest tabulated value on one row and is interpolated on the other.", "The injection pressure, which is the only quantity that still moves once the depth has saturated."]'::jsonb, 0, 'At 1214.7 psia the injection pressure at that row is 1460.125387434 psia against a production pressure of 1146.700000000 psia, nowhere near the 100.0 psi the case declares.'),
  ('gaslift', 'advanced', 'final', null, 16, 'A candidate lands the bottom mandrel of a string exactly at the depth this calculation returns. What has that design given away?', '["The minimum spacing between the last two mandrels, which is checked everywhere in the string except at the target depth branch and so cannot be relied on at the bottom of a design that was placed by this calculation.", "Every allowance the ceiling never contained: nothing for a heavier traverse, nothing for a compressor that drifts, and none of the spacing rules that produce a real string.", "The transfer differential, which is consumed by the crossing condition and therefore cannot also be spent on the handover into the bottom valve.", "The orifice at the packer, since a crossing depth is where a charged valve belongs and not where an orifice does."]'::jsonb, 1, 'The calculation answers one question, how deep gas gets on one column against one table with one margin, and it was never a recommendation.'),
  ('gaslift', 'advanced', 'final', null, 17, 'A manager asks how many extra barrels come from a 50 psi lift in surface injection pressure, having been shown the depth move from 7236.797664483 to 7739.815725361 ft. What is the honest answer?', '["The extra depth can be converted, because the crossing returns the production pressure at the point of injection and a difference in that pressure is a difference in drawdown against the reservoir the well is producing from.", "The conversion needs the flowing traverse, which the caller already supplied, so it can be done inside the same run at no extra cost once the crossing has been located.", "The module reports feet and cannot convert them, since it carries no inflow relation anywhere.", "The gain is proportional to the depth won, because the exchange rate between surface pressure and depth is close to constant across that part of the sweep."]'::jsonb, 2, 'Turning feet into barrels is a nodal calculation somebody else has to do, and every row this function returns is a statement about pressures at a depth.'),
  ('gaslift', 'advanced', 'final', null, 18, 'Sweeping the transfer differential from 0.0 to 50.0 psi returns the same depth at every step, and the study concludes that the differential does not move the injection point. Where did the study go wrong?', '["The differential was swept below the value the crossing condition requires, so the function fell back to its default of 100.0 psi and returned the published answer at every point in the sweep.", "The sweep held the surface injection pressure fixed, and the differential only reaches the depth through the injection side of the crossing, which that pressure had already saturated.", "The steps were too coarse to see the flip.", "The answer had clamped to the deepest tabulated row, so the differential was not what was binding on any of those runs."]'::jsonb, 3, 'At 75.0 psi it returns 7949.755733309 ft and the field turns to pressure, and from there to 200.0 psi the cost runs at much the same feet per psi.'),
  ('gaslift', 'advanced', 'final', null, 19, 'A run comes back with a depth of 0 ft and limitedBy reported as pressure, and an engineer reads it as an injection point at the wellhead. What does the pair actually mean?', '["The gas lost at the very first tabulated row, which is this function''s way of saying the well will not lift at all on that injection pressure.", "The crossing was found above the shallowest row, so the depth was clipped to zero.", "The traverse was rejected as invalid, and a depth of zero reported as limited by pressure is the pair this function returns whenever it cannot use the table it was handed.", "The transfer differential exceeded the whole pressure available, so no margin was left."]'::jsonb, 0, 'That return is one of three, and the only one of the three that represents a crossing anybody solved for reports a depth above the end of the table.'),
  ('gaslift', 'advanced', 'final', null, 20, 'A flowing traverse arrives from a nodal model with the wrong holdup in it, and the crossing comes back to nine decimal places. What does the function do about the error it was handed?', '["It refuses the table, because a traverse that does not rise monotonically with depth cannot be interpolated and the function raises a warning rather than returning a crossing it cannot stand behind.", "Nothing whatever, since it does not validate the table: the crossing is exactly as good as the rows passed in.", "It flags the rows whose curvature is inconsistent with the gas column it marched, which is the one internal consistency check the module runs on an input it did not compute.", "It reports a larger residual, since the two chords end up further apart."]'::jsonb, 1, 'No field in the result carries the row spacing or the provenance of the table, so a report that omits them cannot be audited later.'),
  ('gaslift', 'advanced', 'final', null, 21, 'Proposing a compressor upgrade, a team asks whether the next 50 psi of surface pressure buys as much hole as the last 50 psi did on the published traverse. What has to be checked before the question can be answered?', '["Whether the traverse was tabulated finely enough, because a coarse table underestimates the depth won per psi and would make the second increment look smaller than it is even where the crossing is genuine.", "Whether the transfer differential is still binding, since below 75.0 psi it stops costing hole and the exchange rate against surface pressure changes shape.", "Whether the crossing has already clamped to the deepest tabulated row, since at 1064.7 psia the field turns to depth.", "Whether the gas gravity matches the gas the compressor will deliver."]'::jsonb, 2, 'Each 50 psi step buys around 500 ft while the answer is a crossing, and it buys nothing at all once the table has run out.'),
  ('gaslift', 'advanced', 'final', null, 22, 'An engineer tightens the acceptance tolerance on the reported residual and applies it to a column study whose rows run from exactly 0.0000e+0 psi at 8 samples up to 4.8890e-3 psi at 2560. Which row does that tolerance pick?', '["The 2560 sample row, since a residual that has risen to a stable value across a refinement is the signature of a converged calculation and the threshold rejects only the unconverged rows below it.", "Whichever row sits just under the threshold, which is the usual behaviour of an acceptance rule applied to a monotone quantity and is why such rules are written against tolerances rather than against sample counts.", "None of them, because the whole study reports residuals far inside the 0.5 psi the function allows itself and no threshold placed inside that band can discriminate between the rows at all.", "The 8 sample row, whose depth of 7739.840298490 ft is the furthest from the converged crossing of anything in that study."]'::jsonb, 3, 'A quantity that increases as the calculation improves is not measuring error, and here it measures how far apart the two chords have drifted.'),
  ('gaslift', 'advanced', 'final', null, 23, 'Asked to verify a returned injection depth rather than take it on trust, which check tells a reviewer something the solver did not already assume?', '["Recomputing the residual at that depth from a converged column and a continuous traverse, or halving the tabulation spacing once and reading whether the depth moves.", "Confirming that the reported residual sits inside the 0.5 psi gate the function allows itself, which is the internal check the solver had already run before it returned the depth.", "Checking that the returned injection and production pressures differ by the declared transfer differential.", "Marching the gas column at a far higher sample count and confirming the depth settles."]'::jsonb, 0, 'An answer that shifts tens of feet when the rows change was never converged, whatever it reported about itself.'),
  ('gaslift', 'advanced', 'final', null, 24, 'A release note records this behaviour as roughly a foot of depth error on the case that ships with the engine, and closes it as cosmetic. Why does that reading understate what was found?', '["The published case is measured against a monotone cubic through its own rows, which is a teaching construct rather than a published curve, so the foot of error quoted in the note is not a golden figure and cannot be compared with anything the engine ships.", "The published traverse barely bends, and the same mechanism on a curved traverse tabulated at 2400.0 ft spacing comes back 60.420814470 ft shallow with a ratio of 678.26.", "A foot of depth is worth several psi of injection pressure at that depth, which is more than the gate allows.", "The note quotes the depth error but not the reported residual, which is the figure the defect is actually about."]'::jsonb, 1, 'The ratio holds near 670 all the way down that refinement, at 689.13, 659.81, 674.71, 669.88, 667.53 and 674.88, which makes it a property of the mechanism rather than of one tabulation.'),
  ('gaslift', 'advanced', 'final', null, 25, 'Holding the injection column converged and varying only the row spacing, the shipped 1000.0 ft tabulation reports 4.8890e-3 psi against a true residual of 1.5833e-1 psi. What has that particular comparison isolated?', '["The march truncation in the gas column, which is what remains once the traverse has been resampled from a continuous curve.", "The gap between the golden answer and the engine answer on the published case.", "The traverse chord on its own, because freezing the column takes the other chord out of the comparison and leaves the row spacing as the only source of the error being measured.", "The floor that refinement never removes, which comes from two formulations rather than from any truncation."]'::jsonb, 2, 'That run answers a different question from the shipped engine line and the two must never be quoted in one breath.'),
  ('gaslift', 'advanced', 'final', null, 26, 'A study keeps halving the traverse rows and finds the depth error settling into thousandths of a foot and then wandering instead of falling. What should it conclude?', '["The refinement has reached the precision of the arithmetic, so the rest is rounding noise.", "The continuous curve behind the refinement is itself only an interpolation of the published rows, so beyond a certain spacing the study is measuring the construct rather than the traverse and should be stopped.", "The crossing has moved onto a different pair of rows, which changes the chord being drawn and puts the sequence onto a new branch that will settle again if the halving continues.", "The traverse chord has stopped being the largest term and the injection curve chord now sets the floor."]'::jsonb, 3, 'Refining past that point buys nothing, which is why the practice is to halve once and read the depth rather than to keep halving.'),
  ('gaslift', 'advanced', 'final', null, 27, 'Every depth error on a curved teaching traverse comes back negative, at every row spacing tried. What does a string built on those crossings inherit?', '["A one directional bias toward shallow, since a chord under a convex traverse sits above the curve, so the point of injection is placed above the depth the gas could actually have reached and no averaging of runs removes it.", "A bias that cancels once several tabulations are averaged.", "A bias toward deep, because a chord that reads the production pressure low lets the gas appear to win further down the hole than it really does.", "No bias at all, since the sign belongs to the teaching construct and not to the function."]'::jsonb, 0, 'A systematic sign is a different object from scatter, and it is the reason the practice is stated as a spacing rule rather than as a tolerance.'),
  ('gaslift', 'advanced', 'final', null, 28, 'A result carries limitedBy of depth together with a small residual, and the report quotes that residual as evidence the depth is sound. What is wrong with the argument?', '["The residual on such a row is computed between the injection pressure and the production pressure at the deepest tabulated depth, which is a genuine subtraction but one made hundreds of psi away from where the transfer differential would have been satisfied.", "No crossing was solved for on that return, so the residual belongs to a comparison the function never made and the row is the end of the table handed back unchanged.", "The residual is quoted in psi where the answer is in feet, so it cannot be converted into a bound on the depth.", "The gate of 0.5 psi is applied only to crossings, so a residual on this row was never tested against anything."]'::jsonb, 1, 'Reading that depth as an achievement is the classic misreading, and the same number comes back at three surface pressures that are not the same system.'),
  ('gaslift', 'advanced', 'final', null, 29, 'A sensitivity study walks the design gas rate in 50 Mscf/d steps from 400 to 1400 Mscf/d, finds the margin identical at every point and reports the design robust. What has it actually measured?', '["The insensitivity of the design to rate, which is a genuine property of a string whose closing test contains no rate term.", "The resolution of the port catalogue, which is what the flat stretch measures.", "Only that the axis had not reached its mechanism, since the target touches the verdict solely through port selection and nothing moves until it crosses a catalogue step, so identical rows are a fact about the axis rather than about the design.", "The stability of the margin under refinement of the injection column."]'::jsonb, 2, 'Halving the step across that stretch returns more identical rows, and the smoothness reads as confidence.'),
  ('gaslift', 'advanced', 'final', null, 30, 'A reviewer imposes a house rule that every sensitivity axis must carry at least twenty points. On which axis does that rule waste the effort, and what would have served better?', '["The decrement axis, where the flip sits inside a tenth of a psi per valve and twenty points spread across the usual band of 20 to 50 psi would step straight over it without registering anything.", "The bellows area axis, where the margin moves smoothly and continuously, so a handful of points and a straight line through them carries every bit of information that twenty points would.", "The unloading gradient axis, where the string changes valve count between rows and a denser sweep simply produces more rows that cannot be compared with one another.", "The gas rate axis, where four points placed at the catalogue crossings resolve more than forty spread evenly."]'::jsonb, 3, 'Forty points on an axis with a step mechanism resolve less than four placed where the mechanism acts, and they cost more.'),
  ('gaslift', 'advanced', 'final', null, 31, 'A plot puts the stage 5 closing margin against the unloading gradient from 0.09 to 0.2 psi/ft and a trend is read off the line. Why is there no trend to read?', '["The string changes underneath the axis, falling from 7 valves at target depth to 4 valves stopping at 4567.931487911 ft, so the rows are comparing different valves in different strings.", "The gradient is a declared input rather than a computed one, so it carries no uncertainty.", "The margin is a sign test, so plotting it against anything produces a step and never a line.", "The gradient reaches the verdict through two channels at once, which cancel."]'::jsonb, 0, 'There is no stage 5 at all on the design built at 0.15 psi/ft, so several of the plotted points are not points on the same quantity.'),
  ('gaslift', 'advanced', 'final', null, 32, 'A design review asks for the closing margin to be moved to a few psi of comfort without disturbing any valve depth. Which input can be dialled to a chosen value and which cannot?', '["The decrement can be dialled, since the margin walks smoothly with it and a tenth of a psi per valve is enough to place the margin anywhere in that band, whereas the transfer differential cannot because it changes the valve count.", "Bellows area moves the margin continuously, while the port comes from a catalogue and jumps it from 0.124769727 to 15.249903355 psi with nothing available in between.", "The transfer differential is continuous and the unloading gradient is not.", "The design gas rate is continuous and the bellows area is not."]'::jsonb, 1, 'A curve fitted through the port sweep would describe a valve catalogue that does not exist.'),
  ('gaslift', 'advanced', 'final', null, 33, 'Between transfer differentials of 60.0 and 80.0 psi a swept design gains a valve while keeping the same multipointing stages. Why can those two rows not be read as one sensitivity?', '["The differential enters both the spacing recursion and the closing test, so its effect on the margin is the sum of two contributions that cannot be separated by holding everything else fixed and walking one axis.", "The multipointing stages are unchanged across those two rows, so there is no sensitivity of the verdict to be read between them at all and the valve count is beside the point.", "The string is a different object at 80.0 psi, so a stage number on one row does not point at the same valve at the same depth as the identical stage number on the other.", "The deepest depth is 9000.000000000 ft on both rows, which means the recursion stopped for a different reason each time."]'::jsonb, 2, 'Between 50.0 and 60.0 psi the verdict gains a stage with the string unchanged, so one axis carries two different kinds of change.'),
  ('gaslift', 'advanced', 'final', null, 34, 'After a decrement sweep has located a flip inside a tenth of a psi per valve, a manager asks which side of that flip the design ought to sit on. What can the sweep contribute to the answer?', '["The direction to move in, since the margin rises as the decrement falls and a design placed on the side where the margin is larger is by construction the more conservative of the two available choices.", "A confidence interval on the verdict, built from the slope of the margin across the flip and the precision to which the decrement can be held in the field by the compressor and the choke.", "Nothing at all, since a flip between two swept points is an artefact of the step size.", "Only the distance to the edge, because no sweep says which verdict is right or what the well will do."]'::jsonb, 3, 'Every row of a sweep holds all the other inputs fixed, so it cannot say what two changes do together either.'),
  ('gaslift', 'advanced', 'final', null, 35, 'A submission contains a decrement sweep at tenths of a psi per valve alongside a convergence study on the injection column, and offers both as evidence that the answer is stable. Which of the two is worth nothing, and why?', '["The column study, because refining the cheap knob leaves the traverse rows that actually decide the depth exactly as they arrived.", "The decrement sweep, because the flip it locates is a property of one published case and would sit somewhere else on a string spaced against different gradients.", "Neither, since both were run at a resolution matched to the mechanism behind their own axis.", "Both, because a sweep and a refinement answer different questions."]'::jsonb, 0, 'One of those two studies chose its resolution from the mechanism and the other chose the knob that was easy to turn.'),
  ('gaslift', 'advanced', 'final', null, 36, 'A graded submission reports an injection depth with limitedBy of pressure and the residual the function printed, and stops there. What is the omission that makes it unauditable, and what closes it?', '["The transfer differential, closed by quoting it beside the depth.", "The tabulation the depth came from, closed by stating the row spacing and reading the depth again after that spacing is halved once, since no field in the result carries it and no reported residual would have flagged it.", "The injection curve sample count, closed by stating which of the two the engine uses.", "The gas gravity and temperature profile, closed by listing them with the inputs."]'::jsonb, 1, 'A depth quoted to nine decimal places on a traverse nobody checked is a precise account of a depth the gas will not reach.'),
  ('gaslift', 'advanced', 'final', null, 37, 'This tier says it teaches one habit applied twice. Which two lines in a design report carry that habit?', '["The stop reason printed beside the valve count, and the limitedBy field printed beside every injection depth, which are the two places where an output that looks like an answer is in fact the end of a search.", "The warning list and the stage table, which between them record every comparison the design function made and are therefore the two things a reviewer reads before anything else in the output.", "The closing margin printed beside every verdict, and a residual recomputed from something the solver did not use.", "The units on every quantity and the provenance of every input, which are the two disciplines that let a graded submission be checked by somebody who did not run it."]'::jsonb, 2, 'One of the two is a number the design function never returns, and the other is a number no internal check can produce.'),
  ('gaslift', 'advanced', 'final', null, 38, 'Sorting the outputs of a design run into decisions and artefacts, an engineer has to place an injection depth of 7739.815725361 ft. Which is it, and what exposes the answer?', '["A decision, exposed by the transfer differential the designer chose, which is the input that fixes how much margin the crossing has to keep and therefore fixes the depth the calculation returns.", "A decision, exposed by the surface injection pressure, since that is the quantity a compressor is bought to deliver and every foot in the answer was purchased with it at a rate the sweep makes visible.", "An artefact, exposed by the reported residual of 4.67696e-3 psi, which is the figure that shows the interpolation settled without ever solving the crossing it was asked for.", "Partly an artefact, exposed by the 1000.0 ft row spacing of the traverse it was interpolated on."]'::jsonb, 3, 'The decrement and the transfer differential are decisions, and a clean warning list is an artefact of a comparison nobody printed.'),
  ('gaslift', 'advanced', 'final', null, 39, 'Comparing a seven valve string that reached target depth with a six valve one that stopped at 7207.583657538 ft, a report lines their stage numbers up side by side. What has it got wrong?', '["A string that stopped short is a different object and its stages do not correspond to the other''s.", "The six valve string was built on a steeper unloading gradient, so its stage casing pressures fall by a different amount at each transfer and the two columns of numbers are on different scales even where the stage numbers happen to match.", "The valve counts differ, so the two designs should first be respaced onto a common decrement before any stage of one is set beside the corresponding stage of the other.", "The stop reasons differ, and a comparison is only valid between two runs that stopped for the same reason and therefore had the same quantity binding at the bottom of the string."]'::jsonb, 0, 'Taking the valve count and the stop reason together is the first thing a reading of a design records, and it is what makes any later comparison legitimate.'),
  ('gaslift', 'advanced', 'final', null, 40, 'An operator asks which of this module''s limits could be lifted by supplying a better input and which could not. How does the answer split?', '["Every limit can be lifted by a better input, since the module declares its gradients rather than solving them and a caller who supplies a measured gradient in place of a declared one removes each refusal in turn.", "Absent physics, meaning the inflow relation and the multiphase outflow, is supplied from outside, while the two pinned divergences are wrong answers inside the code that no input repairs.", "The static annulus can be lifted by supplying an injection rate, and the rest are permanent.", "The refusals are all documented in the header, so they are all equally a matter of what the caller supplies."]'::jsonb, 1, 'A report relying on either divergence has to state it, because one of them makes a confident verdict on the wrong fluid and the other reports a residual that cannot see its own error.'),
  ('gaslift', 'advanced', 'final', null, 41, 'A revised nodal model changes the flowing traverse handed to a completed gas lift design. Which part of that design has to be recomputed, and which does not?', '["The valve settings, because the dome charges are set against the pressure at valve depth and the traverse is what fixes that pressure on the production side of every valve in the string.", "The unloading sequence, since the production pressure quoted in every stage row is read from the traverse and a change to it moves the closing margin at every stage of the run.", "The deepest injection point, since the traverse is the whole production side of that crossing, while the spacing recursion runs on declared gradients and never sees the traverse at all.", "Nothing, because the traverse enters only as a table of rows and the design was spaced before it was supplied."]'::jsonb, 2, 'That split is the reason a gas lift design is described as downstream of a nodal model, inheriting whatever that model got wrong on one side of the calculation only.'),
  ('gaslift', 'advanced', 'final', null, 42, 'A report prints every quantity in a design to nine decimal places and offers that as evidence of a careful calculation. What does the precision establish?', '["That the arithmetic was carried at double precision throughout, which is the only claim a digit count can support, and which matters here because the closing test subtracts two numbers of comparable size at every stage of the sequence.", "That the run is reproducible, since a reader given the same inputs can confirm every figure to the last digit and can therefore rerun the design and check that the engine has not changed underneath the report.", "That the engine and its independent check agree, since the published designs match on every stage and the digits printed are what makes that agreement visible to a reviewer reading the two side by side.", "Nothing about stability, since the deciding verdict of that string still turns on a fraction of a psi."]'::jsonb, 3, 'Precision in a report is not stability in an answer, and the two numbers worth printing are a margin and a row spacing.');
